        if (typeof attachment.attachmentId !== "string" || attachment.attachmentId === "") continue;
        refs.push({
          attachmentId: attachment.attachmentId,
          mediaType: typeof attachment.mediaType === "string" ? attachment.mediaType : "image/png",
          name: typeof attachment.name === "string" ? attachment.name : "image.png",
        });
      }
      return refs;
    }

    /**
     * 是否含有无法重发的 file 分片（文件回执只对原会话有效）。
     * @param content - 消息内容分片数组。
     * @returns 含 file 分片时为 true。
     */
    function hasFilePart(content) {
      if (!Array.isArray(content)) return false;
      return content.some((part) => part !== null && typeof part === "object" && part.type === "file");
    }

    /**
     * 字节转 base64（分块，避免超长参数把调用栈撑爆）。
     * @param bytes - 图片字节。
     * @returns base64 字符串。
     */
    function base64Of(bytes) {
      let binary = "";
      const chunk = 0x8000;
      for (let index = 0; index < bytes.length; index += chunk) {
        binary += String.fromCharCode(...bytes.subarray(index, index + chunk));
      }
      return btoa(binary);
    }

    /** 注入动作行后的按钮标记：同时作为样式钩子，避免依赖宿主的哈希类名。 */
    const ROW_MARK = "data-dsh-edit-question";

    /**
     * 找本轮开场提问的「时间 + 复制」动作行（宿主私有渲染，没有对外插槽）。
     * 宿主在消息流条目上标注 data-chat-flow-kind / data-chat-turn，动作行本身标注 data-clock
     * （用户消息为 start），这两个属性是它做滚动定位与悬停淡入用的公共契约，比哈希类名稳定；
     * 同一轮若有多条用户消息（排队插话），querySelector 取第一条，即该轮的开场提问。
     * @param turnId - 轮次号。
     * @returns 动作行元素；该提问不在 DOM 中（虚拟化回收或尚未渲染）时为 null。
     */
    function findActionRow(turnId) {
      if (turnId === undefined) return null;
      const item = document.querySelector(`[data-chat-flow-kind="user"][data-chat-turn="${String(turnId)}"]`);
      if (item === null || item.hasAttribute("hidden")) return null;
      return item.querySelector("[data-clock=\"start\"]");
    }

    /**
     * 跟踪动作行元素：挂载时解析一次，之后用 childList 观察（虚拟化回收、重渲染换掉节点后重新解析）。
     * 目标仍然挂在文档上就直接返回，流式渲染期间不会反复查询；只有真的换了元素才 setState。
     * @param turnId - 轮次号。
     * @returns 当前可用的动作行；找不到时为 null（此时按钮退回轮尾单独一行）。
     */
    function useActionRow(turnId) {
      const [row, setRow] = react.useState(null);
      react.useEffect(() => {
        if (turnId === undefined) return undefined;
        let current = null;
        let frame = 0;
        const settle = () => {
          if (current !== null && current.isConnected) return;
          const next = findActionRow(turnId);
          current = next;
          setRow((previous) => (previous === next ? previous : next));
        };
        settle();
        const observer = new MutationObserver(() => {
          if (frame !== 0) return;
          frame = window.requestAnimationFrame(() => {
            frame = 0;
            settle();
          });
        });
        observer.observe(document.body, { childList: true, subtree: true });
        return () => {
          observer.disconnect();
          if (frame !== 0) window.cancelAnimationFrame(frame);
        };
      }, [turnId]);
      return row;
    }

    /**
     * fork 切点。必须是「提问之前的最后一个已完成轮次」的 turn/end 事件 seq：
     * 该边界上 agent inbox 已被消费干净，切点之后的提问不会被继承。
     * 首轮没有可继承的历史，切到 0（只保留会话元信息事件，不含任何提问），
     * 否则会落在提交提问时写入 inbox 的 agent/inbox/spliced 上，使原提问在新会话里再执行一次。
     *
     * 会话历史是分页加载的（页边界对齐到轮次开始），长会话滚到中间时，「上一轮的 turn/end」
     * 可能还没进快照。此时绝不能退化成 0——0 等于新会话从零开始，会静默丢掉全部历史。
     * 所以返回 issue 让对话框拦截，而不是给出一个看着能用、实际是错的切点。
     * @param snapshot - Chat 快照。
     * @param turnId - 轮次号。
     * @returns 切点与问题标记；issue 为 null 表示切点可信。
     */
    function cutOf(snapshot, turnId) {
      if (snapshot === undefined || turnId === undefined) return { atSeq: 0, issue: "unknown" };
      const timeline = snapshot.timeline;
      if (timeline === undefined || !Array.isArray(timeline.turnOrder) || timeline.turns === undefined) return { atSeq: 0, issue: "unknown" };
      const index = timeline.turnOrder.indexOf(turnId);
      if (index < 0) return { atSeq: 0, issue: "unknown" };
      if (index === 0) {
        // 只有轮次号 1 才是真的首轮：前面本来就没有历史，0 才是正确切点。
        // 长会话按页加载（maxMessages 500 / minTurns 2，页边界切在某一轮的 turn/start 上），
        // 窗口里的第一轮往往不是会话的第一轮，它前面的轮次根本没进快照，切点无从计算。
        return turnId === 1 ? { atSeq: 0, issue: null } : { atSeq: 0, issue: "missingPrevious" };
      }
      const previousTurn = timeline.turnOrder[index - 1];
      const previous = timeline.turns.get(previousTurn);
      // 上一轮整轮都没进快照（分页窗口只加载到本轮）。
      if (previous === undefined) return { atSeq: 0, issue: "missingPrevious" };
      const end = previous.end;
      // 上一轮有节点但没有结束位置：还在生成，或结束事件落在未加载的页里。
      if (end === undefined || typeof end.seq !== "number" || end.seq <= 0) return { atSeq: 0, issue: "missingEnd" };
      return { atSeq: end.seq, issue: null };
    }

    /**
     * 切点诊断：把 cutSeqOf 依赖的 timeline 事实原样带出来，供点按钮时打日志。
     * 切点算错时，这里能直接看出是「找不到该轮」「上一轮缺 end」还是「end.seq 为 0」。
     * @param snapshot - Chat 快照。
     * @param turnId - 轮次号。
     * @returns 可 JSON 化的诊断对象。
     */
    function probeCut(snapshot, turnId) {
      const timeline = snapshot === undefined ? undefined : snapshot.timeline;
      if (timeline === undefined || !Array.isArray(timeline.turnOrder) || timeline.turns === undefined) {
        return { turnId, reason: "no-timeline" };
      }
      const index = timeline.turnOrder.indexOf(turnId);
      const previous = index > 0 ? timeline.turns.get(timeline.turnOrder[index - 1]) : undefined;
      const end = previous === undefined ? undefined : previous.end;
      return {
        turnId,
        index,
        total: timeline.turnOrder.length,
        order: timeline.turnOrder.slice(-8),
        previousTurn: index > 0 ? timeline.turnOrder[index - 1] : null,
        hasPrevious: previous !== undefined,
        previousStatus: previous === undefined ? null : (previous.status ?? null),
        previousKeys: previous === undefined ? null : Object.keys(previous).slice(0, 12),
        endSeq: end === undefined ? null : (typeof end === "object" ? (end.seq ?? null) : end),
      };
    }

    /**
     * 生成可读的错误文本。
     * @param error - 任意抛出物。
     * @returns 文本。
     */
    function describe(error) {
      if (error === null || error === undefined) return "";
      if (typeof error === "string") return error;
      if (typeof error.message === "string" && error.message !== "") return error.message;
      return String(error);
    }

    /**
     * 建立一个会话的编辑器状态与动作（每个会话一份）。
     * @param ctx - 客户端根上下文。
     * @param sessionId - 会话标识。
     * @returns 编辑器：状态源 + 打开/编辑/提交/关闭动作。
     */
    function createEditor(ctx, sessionId) {
      const store = createSnapshotStore(CLOSED);
      const patch = (fields) => {
        store.set({ ...store.getSnapshot(), ...fields });
      };
      /** 自动补历史进行中，防止重入。 */
      let loadingHistory = false;
      /**
       * 预读原提问里的图片，转成 data URL 供对话框显示缩略图。
       * 单张读失败时留空（仍可删除），不影响其余图片。
       * @param images - 原图引用列表。
       * @param userSeq - 打开时的用户消息 seq，用于丢弃过期回调。
       */
      async function loadOriginalPreviews(images, userSeq) {
        try {
          const previews = await ctx.sessions.using(sessionId, { source: "edit-question" }, async (reference) => {
            const binding = await reference.ready;
            const out = [];
            for (const image of images) {
              try {
                const result = await binding.session.readAttachment(image.attachmentId);
                if (result.ok !== true) {
                  out.push(null);
                  continue;
                }
                const mediaType = typeof image.mediaType === "string" ? image.mediaType : "image/png";
                out.push(`data:${mediaType};base64,${base64Of(result.value.data)}`);
              } catch (error) {
                console.warn("[dsh-edit-question] preview read failed:", image.attachmentId, error);
                out.push(null);
              }
            }
            return out;
          });
          const snapshot = store.getSnapshot();
          if (!snapshot.open || snapshot.userSeq !== userSeq) return;
          patch({
            images: snapshot.images.map((image, index) => (typeof previews[index] === "string" ? { ...image, preview: previews[index] } : image)),
          });
        } catch (error) {
          console.warn("[dsh-edit-question] preview load failed:", error);
        }
      }
      /**
       * 自动补历史的轮询任务：宿主不会给 slot 组件跑 useEffect（实测 effect 一次都不执行），
       * 所以这里不依赖 React 生命周期，直接在打开编辑器时启动，靠轮询 store 状态决定何时停止。
       */
      async function beginAutoLoad() {
        if (loadingHistory) return;
        loadingHistory = true;
        patch({ loadingHistory: true });
        try {
          for (let attempt = 0; attempt < 40; attempt++) {
            const current = store.getSnapshot();
            if (current.open !== true || current.issue === null) break;
            const button = loadEarlierButton();
            if (button === null) {
              scrollChatToTop();
              await wait(600);
              continue;
            }
            console.info(`[dsh-edit-question] auto load earlier (attempt ${String(attempt + 1)})`);
            button.click();
            await wait(1800);
          }
        } catch (error) {
          console.warn("[dsh-edit-question] auto load failed:", error);
        } finally {
          loadingHistory = false;
          const current = store.getSnapshot();
          if (current.open === true) patch({ loadingHistory: false });
          scrollChatToTurn(current.turnId);
        }
      }

      return {
        store,
        /**
         * 打开编辑器。
         * @param input - 目标提问：切点 seq、用户消息 seq、原文、图片引用、是否含文件回执。
         */
        open(input) {
          const images = Array.isArray(input.images) ? input.images : [];
          const issue = typeof input.issue === "string" ? input.issue : null;
          store.set({
            open: true,
            text: input.text,
            busy: false,
            error: null,
            atSeq: input.atSeq,
            userSeq: input.userSeq,
            turnId: typeof input.turnId === "number" ? input.turnId : -1,
            images,
            extraImages: EMPTY_IMAGES,
            files: input.files === true,
            issue,
            loadingHistory: false,
            removeOriginal: true,
          });
          // 缩略图必须读回字节才能显示；attachment 只对原会话授权，所以在这里读。
          if (images.length > 0) void loadOriginalPreviews(images, input.userSeq);
          // 切点不可信时立刻开始自动补历史，用户不用滚回顶部手动点「加载更早」。
          if (issue !== null) void beginAutoLoad();
        },
        /** 关闭编辑器并丢弃草稿。 */
        dismiss() {
          if (store.getSnapshot().busy) return;
          store.set(CLOSED);
        },
        /**
         * 更新草稿文本。
         * @param text - 新文本。
         */
        edit(text) {
          patch({ text });
        },
        /**
         * 追加对话框里补充的图片（由组件读成 base64 后交过来）。
         * @param images - 追加项：{ mediaType, data, preview, name }。
         */
        addImages(images) {
          if (!Array.isArray(images) || images.length === 0) return;
          const current = store.getSnapshot().extraImages;
          patch({ extraImages: [...current, ...images].slice(0, MAX_ADDED_IMAGES) });
        },
        /**
         * 移除一张补充的图片。
         * @param index - 补充列表里的下标。
         */
        removeImage(index) {
          const current = store.getSnapshot().extraImages;
          patch({ extraImages: current.filter((_, position) => position !== index) });
        },
        /**
         * 从原图里移除一张：重发时不再带上它。
         * @param index - 原图列表下标。
         */
        removeOriginalImage(index) {
          const current = store.getSnapshot().images;
          patch({ images: current.filter((_, position) => position !== index) });
        },
        /**
         * 选择重发后是否归档原会话。
         * @param removeOriginal - true 表示新会话建好后归档原会话。
         */
        setRemoveOriginal(removeOriginal) {
          patch({ removeOriginal });
        },
        /**
         * 用目标轮按钮组件实时算出的切点刷新编辑器：历史补进来之后 issue 会自动清空。
         * 非目标轮的按钮也会调用这里，靠 turnId 过滤。
         * @param cut - { atSeq, issue, turnId }。
         */
        applyCut(cut) {
          const state = store.getSnapshot();
          if (state.open !== true || state.turnId !== cut.turnId) return;
          const nextIssue = typeof cut.issue === "string" ? cut.issue : null;
          const nextAtSeq = typeof cut.atSeq === "number" ? cut.atSeq : state.atSeq;
          if (state.issue === nextIssue && state.atSeq === nextAtSeq) return;
          patch({ atSeq: nextAtSeq, issue: nextIssue });
        },
        /**
         * 提交：读回原提问的图片 → fork 出截断后的新会话 → 在新会话重发 →（可选）归档原会话 → 打开新会话。
         * 错误只记录「错误码 + 细节」，文案由对话框组件按当前语言渲染。
         */
        async submit() {
          const state = store.getSnapshot();
          if (state.busy) return;
          const text = state.text.trim();
          const images = state.images;
          const extra = state.extraImages;
          if (text === "" && images.length === 0 && extra.length === 0) return;
          // 切点不可信时一律不提交：静默从 0 重开会丢掉全部历史，比拒绝提交更糟。
          if (state.issue !== null) return;
          // fork 的 atSeq 必须是真实存在的事件 seq：切点由按钮侧算好；首轮为 0（只继承会话元信息）。
          const atSeq = state.atSeq >= 0 ? state.atSeq : 0;
          if (state.userSeq < 0) {
            patch({ error: { code: "noTarget", detail: "" } });
            return;
          }
          patch({ busy: true, error: null });
          // 补充的图片已经在对话框里读成 base64，直接按 content part 组装。
          const addedParts = extra.map((image) => ({ type: "image", mediaType: image.mediaType, data: image.data }));
          // 原图要在原会话上读：session.attachment 只授权给日志里引用过它的会话，fork 出的新会话还没有这条引用。
          let imageParts = addedParts;
          if (images.length > 0) {
            try {
              const originalParts = await ctx.sessions.using(sessionId, { source: "edit-question" }, async (reference) => {
                const binding = await reference.ready;
                const parts = [];
                for (const image of images) {
                  const result = await binding.session.readAttachment(image.attachmentId);
                  if (result.ok !== true) throw new Error(result.error === undefined ? image.attachmentId : describe(result.error));
                  parts.push({ type: "image", mediaType: image.mediaType, data: base64Of(result.value.data) });
                }
                return parts;
              });
              imageParts = [...originalParts, ...addedParts];
            } catch (error) {
              patch({ busy: false, error: { code: "attachment", detail: describe(error) } });
              console.error("[dsh-edit-question] read attachment failed:", error);
              return;
            }
          }
          let childId;
          try {
            childId = await ctx.sessions.fork({ sessionId, atSeq, increaseTitle: true });
            console.info(`[dsh-edit-question] forked ${sessionId} at seq ${String(atSeq)} -> ${childId}`);
          } catch (error) {
            patch({ busy: false, error: { code: "fork", detail: describe(error) } });
            console.error("[dsh-edit-question] fork failed:", error);
            return;
          }
          try {
            await ctx.sessions.using(childId, { source: "edit-question" }, async (reference) => {
              const binding = await reference.ready;
              await binding.session.prompt([...imageParts, { type: "text", text }], "queue");
            });
          } catch (error) {
            // 会话已经建好，只是首发失败：保留 childId 让用户能在新会话里手动重发。
            patch({ busy: false, error: { code: "prompt", detail: describe(error) } });
            console.error("[dsh-edit-question] prompt failed:", error);
            return;
          }
          // 归档（DSH 没有物理删除会话的接口）失败不影响新会话：只记录告警。
          if (state.removeOriginal && typeof ctx.uiWorkspace.archiveSession === "function") {
            try {
              await ctx.uiWorkspace.archiveSession(sessionId, { stopActivity: true });
              console.info(`[dsh-edit-question] archived original ${sessionId}`);
            } catch (error) {
              console.warn("[dsh-edit-question] archive original failed:", error);
            }
          }
          store.set(CLOSED);
          ctx.uiWorkspace.openSession(childId);
        },
      };
    }

    /** 轮尾退化位置的按钮样式（拿不到动作行时用）：右对齐并贴在该轮动作行之上。 */
    const tailActionStyle = {
      display: "inline-flex",
      alignItems: "center",
      gap: "4px",
      margin: "0 0 2px auto",
      padding: "1px 6px",
      border: "1px solid transparent",
      borderRadius: "var(--dsw-radius-sm, 6px)",
      background: "transparent",
      color: "var(--dsw-alias-label-tertiary, #8a8f98)",
      font: "inherit",
      fontSize: "var(--dsw-font-xs-13, 12px)",
      lineHeight: "18px",
      cursor: "pointer",
      opacity: 0.85,
    };

    /**
     * 注入用户消息动作行后的按钮样式：该行是 28px 高的 flex 行（时间 + 复制图标，gap 8px），
     * 所以按钮只占 22px 高、不加外边距，保持与图标同一基线。
     */
    const rowActionStyle = {
      display: "inline-flex",
      alignItems: "center",
      gap: "4px",
      height: "22px",
      margin: 0,
      padding: "0 5px",
      border: "1px solid transparent",
      borderRadius: "var(--dsw-radius-sm, 6px)",
      background: "transparent",
      color: "var(--dsw-alias-label-tertiary, #8a8f98)",
      font: "inherit",
      fontSize: "var(--dsw-font-xs-13, 12px)",
      lineHeight: "18px",
      whiteSpace: "nowrap",
      cursor: "pointer",
      opacity: 0.9,
    };

    /** 悬停态（两种位置共用）：提亮文字并铺一层浅背景，与宿主图标按钮的 hover 一致。 */
    const hoverStyle = {
      color: "var(--dsw-alias-label-primary, #1f2329)",
      background: "var(--dsw-alias-interactive-bg-hover, rgba(0,0,0,.05))",
      opacity: 1,
    };

    /**
     * 「编辑提问」入口：先做能力守卫，再交给内部组件（内部无条件调用全部 hook）。
     * @param props - 轮次位置、会话标准工具包与注入的编辑器动作。
     * @returns 按钮；该轮没有可定位的提问或缺少工具包时返回 null。
     */
    function EditQuestionAction(props) {
      if (typeof props.useChat !== "function" || props.t === undefined) return null;
      return h(EditQuestionActionButton, props);
    }

    /**
     * 「编辑提问」按钮本体：渲染到该轮提问的「时间 + 复制」动作行里；拿不到该行时退回轮尾一行。
     * @param props - 轮次位置、会话标准工具包与注入的编辑器动作。
     * @returns 按钮；该轮没有可定位的提问时返回 null。
     */
    function EditQuestionActionButton(props) {
      const { turn, sessionId, useChat, t, openEditor, editDraft, applyCut } = props;
      const turnId = turnIdOf(turn);
      const row = useActionRow(turnId);
      // 选择器只返回原始值，避免每次渲染产生新对象导致的重复订阅。
      const userSeq = useChat((snapshot) => {
        const node = openingUserNode(snapshot, turnId);
        return node === undefined ? -1 : node.data.seq;
      });
      const atSeq = useChat((snapshot) => cutOf(snapshot, turnId).atSeq);
      const cutIssue = useChat((snapshot) => cutOf(snapshot, turnId).issue);
      const draft = useChat((snapshot) => {
        const node = openingUserNode(snapshot, turnId);
        return node === undefined ? "" : textOf(node.data.content);
      });
      // 图片/文件分片留到点击时再解析：useChat 的 selector 每次返回新数组会让宿主每帧判定「变了」，
      // 因此这里只订阅一个稳定标量，把最新 content 存在 ref 里。
      const openingContent = react.useRef(null);
      useChat((snapshot) => {
        const node = openingUserNode(snapshot, turnId);
        openingContent.current = node === undefined ? null : node.data.content;
        return node === undefined ? 0 : 1;
      });
      const cutProbe = react.useRef(null);
      useChat((snapshot) => {
        cutProbe.current = probeCut(snapshot, turnId);
        return 0;
      });
      // 宿主不触发 slot 组件的 useEffect，但 useChat 的 selector 会在渲染期执行：
      // 把「切点回写」放进 selector，用 setTimeout 推到渲染结束之后，避免在渲染期改 store。
      const lastCut = react.useRef({ atSeq: -1, issue: null });
      useChat((snapshot) => {
        const cut = cutOf(snapshot, turnId);
